import re


_APPEAL_LABEL = "Appeal from the United States District Court"
_STOP_LABELS = ("SUMMARY",)


def rule_us_district_court_origin(doc: dict) -> list[dict]:
    try:
        spans = []
        seen = set()

        def add_span(text: str, source_item: dict) -> None:
            cleaned = re.sub(r"\s+", " ", (text or "")).strip().rstrip(".,;:")
            if not cleaned:
                return
            key = cleaned.lower()
            if key in seen:
                return
            seen.add(key)
            span = {"text": cleaned}
            for field in ("page_no", "line_no", "paragraph_no"):
                if field in source_item:
                    span[field] = source_item[field]
            spans.append(span)

        def scan_items(items: list[dict]) -> None:
            limit = min(len(items or []), 120)
            for i in range(limit):
                item = items[i] or {}
                text = (item.get("text") or "").strip()
                if not text:
                    continue

                upper = text.upper()
                if any(upper.startswith(stop) for stop in _STOP_LABELS):
                    break

                label_pos = text.find(_APPEAL_LABEL)
                if label_pos < 0:
                    continue

                remainder = text[label_pos + len(_APPEAL_LABEL):].strip()
                if remainder:
                    # Some OCR variants keep the district line on the same row.
                    if remainder.lower().startswith("for the "):
                        add_span(remainder, item)
                        continue

                for j in range(i + 1, min(limit, i + 6)):
                    next_item = items[j] or {}
                    next_text = (next_item.get("text") or "").strip()
                    if not next_text:
                        continue

                    next_upper = next_text.upper()
                    if any(next_upper.startswith(stop) for stop in _STOP_LABELS):
                        break

                    if next_text.lower().startswith("for the "):
                        add_span(next_text, next_item)
                        break

                    # A few pages may omit the literal "for the" prefix.
                    if (
                        "judge" not in next_text.lower()
                        and re.search(r"(?i)\b(?:district|circuit)\b", next_text)
                    ):
                        add_span(next_text, next_item)
                        break

        def scan_history_items(items: list[dict]) -> None:
            for i, item in enumerate(items or []):
                text = (item or {}).get("text") or ""
                lower = text.lower()
                if "appeal" not in lower or "united states district court for the" not in lower:
                    continue

                tail = text.split("United States District Court for the", 1)[1].strip()
                if tail:
                    add_span(tail.split(",")[0].strip(), item)
                else:
                    for j in range(i + 1, min(len(items or []), i + 4)):
                        next_item = items[j] or {}
                        next_text = (next_item.get("text") or "").strip()
                        if not next_text:
                            continue
                        if "judge" in next_text.lower():
                            continue
                        if re.search(r"(?i)\bdistrict\b", next_text):
                            add_span(next_text.split(",")[0].strip(), next_item)
                            break

                for j in range(i + 1, min(len(items or []), i + 60)):
                    next_item = items[j] or {}
                    next_text = (next_item.get("text") or "").strip()
                    if not next_text:
                        continue
                    if "judge" in next_text.lower():
                        continue
                    if "united states district court for the" not in next_text.lower():
                        continue
                    district_tail = next_text.split("United States District Court for the", 1)[1].strip()
                    if district_tail:
                        add_span(district_tail.split(",")[0].strip(), next_item)

        scan_items(doc.get("lines") or [])
        scan_items(doc.get("paragraphs") or [])
        scan_history_items(doc.get("lines") or [])
        scan_history_items(doc.get("paragraphs") or [])

        if not spans:
            full_text = doc.get("text") or ""
            for match in re.finditer(re.escape(_APPEAL_LABEL), full_text):
                start = match.end()
                tail = full_text[start:start + 180]
                tail = tail.lstrip(" \t\r\n")
                line = tail.splitlines()[0].strip() if tail else ""
                if line.lower().startswith("for the "):
                    add_span(line, {})

        return spans
    except Exception:
        return []

import re


_COURT_LINE_RE = re.compile(
    r"(?i)\b(?:united states district court|u\.s\. district court|"
    r"(?:north|south|east|west|central|middle)ern?\s+district\s+of\b|"
    r"district of\b)"
)
_TITLE_STOP_RE = re.compile(
    r"(?i)\b(?:respondent|petition|order|opinion|before:|argued|submitted|filed|"
    r"summary|counsel|judge|presiding)\b"
)
_CITY_CONT_RE = re.compile(r"^[A-Z][A-Za-z.'-]*(?:\s+[A-Z][A-Za-z.'-]*)*(?:,)?$")


def rule_district_court_caption_fallback(doc: dict) -> list[dict]:
    try:
        lines = [
            item
            for item in (doc.get("lines") or [])
            if isinstance(item, dict)
        ]
        lines = sorted(
            lines,
            key=lambda x: (
                x.get("page_no", 10**9),
                x.get("line_no", 10**9),
            ),
        )

        spans = []
        seen = set()

        def add_span(text: str, source: dict) -> None:
            cleaned = " ".join(text.split()).strip()
            if not cleaned or cleaned in seen:
                return
            span = {"text": cleaned}
            for key in ("page_no", "line_no", "paragraph_no"):
                value = source.get(key)
                if value is not None:
                    span[key] = value
            spans.append(span)
            seen.add(cleaned)

        for i, item in enumerate(lines[:90]):
            text = " ".join((item.get("text") or "").split())
            if not text:
                continue

            if "appeal from" in text.lower():
                continue

            if _COURT_LINE_RE.search(text):
                collected = [text]
                for j in range(i + 1, min(i + 5, len(lines))):
                    next_text = " ".join((lines[j].get("text") or "").split())
                    if not next_text:
                        if collected:
                            break
                        continue
                    if _TITLE_STOP_RE.search(next_text):
                        break
                    collected.append(next_text)
                add_span("\n".join(collected), item)
                continue

            prev_window = " ".join(
                " ".join((lines[k].get("text") or "").split())
                for k in range(max(0, i - 4), i)
            ).lower()
            if "d.c. no." not in prev_window and "no." not in prev_window:
                continue

            if not re.search(
                r"(?i)\b(?:northern|southern|eastern|western|central|middle)\s+district\s+of\b|\bdistrict\s+of\b",
                text,
            ):
                continue

            collected = [text]
            for j in range(i + 1, min(i + 4, len(lines))):
                next_text = " ".join((lines[j].get("text") or "").split())
                if not next_text:
                    if collected:
                        break
                    continue
                if _TITLE_STOP_RE.search(next_text):
                    break
                if _CITY_CONT_RE.match(next_text) or _COURT_LINE_RE.search(next_text):
                    collected.append(next_text)
                    continue
                break
            add_span("\n".join(collected), item)

        return spans
    except Exception:
        return []

import re


_HEADER_RE = re.compile(
    r"^\s*Appeals?\s+from\s+the\s+(?:United\s+States\s+)?District\s+Court\b",
    re.IGNORECASE,
)
_STOP_RE = re.compile(
    r"(?i)\b(?:before:|opinion|summary|counsel|argued|submitted|filed|order|"
    r"district judge|magistrate judge|circuit judges?|judge\b|presiding)\b"
)


def rule_appeal_from_us_district_court_header(doc: dict) -> list[dict]:
    try:
        lines = [
            item
            for item in (doc.get("lines") or [])
            if isinstance(item, dict)
        ]
        lines = sorted(
            lines,
            key=lambda x: (
                x.get("page_no", 10**9),
                x.get("line_no", 10**9),
            ),
        )

        spans = []
        seen = set()

        for i, item in enumerate(lines):
            if i > 120:
                break

            first_text = " ".join((item.get("text") or "").split())
            if not first_text or not _HEADER_RE.search(first_text):
                continue

            collected = [first_text]
            for j in range(i + 1, min(i + 5, len(lines))):
                text = " ".join((lines[j].get("text") or "").split())
                if not text:
                    if collected:
                        break
                    continue
                if _STOP_RE.search(text):
                    break
                collected.append(text)

            span_text = "\n".join(collected).strip()
            if not span_text or span_text in seen:
                continue

            span = {"text": span_text}
            for key in ("page_no", "line_no", "paragraph_no"):
                value = item.get(key)
                if value is not None:
                    span[key] = value
            spans.append(span)
            seen.add(span_text)

        return spans
    except Exception:
        return []

def _coerce_span(entry: Any) -> dict[str, Any] | None:
    if isinstance(entry, str):
        text = entry.strip()
        return {"text": text} if text else None
    if not isinstance(entry, dict):
        return None
    text = entry.get("text")
    if text is None:
        return None
    text = str(text)
    if not text.strip():
        return None
    coerced = dict(entry)
    coerced["text"] = text
    return coerced


def _span_key(span: dict[str, Any]) -> tuple[Any, ...]:
    return (
        span.get("page_no"),
        span.get("paragraph_no"),
        span.get("line_no"),
        span.get("text"),
    )


def _sort_key(span: dict[str, Any]) -> tuple[Any, ...]:
    return (
        span.get("page_no", 10**9),
        span.get("paragraph_no", 10**9),
        span.get("line_no", 10**9),
        span.get("text", ""),
    )


def _list_rule_files(rules_dir: Path, rule_names: list[str] | None = None) -> list[Path]:
    if rule_names:
        files = [rules_dir / f"{name}.py" for name in rule_names]
        return [path for path in files if path.exists()]
    return sorted(path for path in rules_dir.glob("rule_*.py") if path.is_file())


def _apply_rule_files(document: dict[str, Any], rule_files: list[Path]) -> dict[str, Any]:
    spans: list[dict[str, Any]] = []
    rules_applied: list[str] = []
    rules_no_hits: list[str] = []
    rule_errors: list[str] = []

    for rule_file in rule_files:
        rule_name = rule_file.stem
        try:
            rule_fn = _load_rule_fn(rule_file)
            raw_result = rule_fn(document)
        except Exception as exc:
            rule_errors.append(f"{rule_name}: {exc}")
            rules_no_hits.append(rule_name)
            continue

        if not isinstance(raw_result, list):
            rules_no_hits.append(rule_name)
            continue

        coerced = [_coerce_span(item) for item in raw_result]
        cleaned = [item for item in coerced if item]
        if cleaned:
            spans.extend(cleaned)
            rules_applied.append(rule_name)
        else:
            rules_no_hits.append(rule_name)

    deduped: list[dict[str, Any]] = []
    seen: set[tuple[Any, ...]] = set()
    for span in spans:
        key = _span_key(span)
        if key in seen:
            continue
        seen.add(key)
        deduped.append(span)

    deduped.sort(key=_sort_key)
    retrieved_text = "\n\n".join(span["text"] for span in deduped) if deduped else ""

    return {
        "retrieved_spans": deduped,
        "retrieved_text": retrieved_text,
        "retrieved_token_count": _count_tokens(retrieved_text),
        "rules_applied": rules_applied,
        "rules_no_hits": rules_no_hits,
        "rule_errors": rule_errors,
    }


def _qa_call(question: str, retrieved_text: str, *, model_name: str = "gpt54") -> tuple[str | None, int, int, float]:
    model_mod = importlib.import_module(f"models.{model_name}")
    t0 = time.time()
    response = model_mod.client.chat.completions.create(
        model=model_mod.AZURE_DEPLOYMENT,
        messages=[
            {"role": "system", "content": _QA_SYSTEM},
            {"role": "user", "content": f"Passage:\n{retrieved_text}\n\nQuestion: {question}"},
        ],
        max_completion_tokens=500,
        temperature=0.0,
    )
    latency = round(time.time() - t0, 3)
    answer = (response.choices[0].message.content or "").strip() or None
    usage = response.usage
    return (
        answer,
        int(usage.prompt_tokens if usage else 0),
        int(usage.completion_tokens if usage else 0),
        latency,
    )


def _judge_call(
    dataset_name: str,
    question: str,
    ground_truth: Any,
    predicted: Any,
) -> tuple[bool, int, int]:
    if ground_truth is None or predicted is None:
        return False, 0, 0

    model_mod = importlib.import_module("models.gpt54")
    gt_str = json.dumps(ground_truth) if not isinstance(ground_truth, str) else ground_truth
    pred_str = str(predicted)
    response = model_mod.client.chat.completions.create(
        model=model_mod.AZURE_DEPLOYMENT,
        messages=[
            {
                "role": "system",
                "content": _JUDGE_SYSTEM_BY_DATASET.get(dataset_name, _JUDGE_SYSTEM_GENERIC),
            },
            {
                "role": "user",
                "content": f"Question: {question}\nGround Truth: {gt_str}\nPredicted: {pred_str}",
            },
        ],
        max_completion_tokens=10,
        temperature=0.0,
    )
    verdict = (response.choices[0].message.content or "").strip().lower()
    usage = response.usage
    return (
        verdict == "correct",
        int(usage.prompt_tokens if usage else 0),
        int(usage.completion_tokens if usage else 0),
    )


def _clean_stderr(stderr: str) -> str:
    lines = [
        line
        for line in stderr.splitlines()
        if line.strip() != "Reading additional input from stdin..."
    ]
    return "\n".join(lines).strip()[:4000]


